import json
import itertools

def solve():
    jobs_data = [
        [[(0, 6), (1, 5)], [(1, 7), (2, 6)], [(0, 5), (2, 8)]], # J0
        [[(0, 5), (2, 7)], [(1, 6), (2, 5)], [(0, 7), (1, 8)]], # J1
        [[(1, 4), (2, 6)], [(0, 8), (1, 7)], [(0, 6), (2, 5)]], # J2
        [[(0, 7), (1, 6)], [(1, 5), (2, 7)], [(0, 4), (2, 6)]]  # J3
    ]

    downtimes = {
        1: [(5, 20)],
        2: [(12, 25)]
    }

    baseline = [
        {"job": 1, "op": 0, "machine": 0, "start": 0, "end": 5, "dur": 5},
        {"job": 0, "op": 0, "machine": 1, "start": 0, "end": 5, "dur": 5},
        {"job": 3, "op": 0, "machine": 0, "start": 5, "end": 12, "dur": 7},
        {"job": 2, "op": 0, "machine": 1, "start": 5, "end": 9, "dur": 4},
        {"job": 0, "op": 1, "machine": 2, "start": 5, "end": 11, "dur": 6},
        {"job": 1, "op": 1, "machine": 1, "start": 9, "end": 15, "dur": 6},
        {"job": 2, "op": 2, "machine": 2, "start": 11, "end": 16, "dur": 5},
        {"job": 3, "op": 1, "machine": 1, "start": 15, "end": 20, "dur": 5},
        {"job": 2, "op": 1, "machine": 0, "start": 16, "end": 24, "dur": 8},
        {"job": 3, "op": 2, "machine": 2, "start": 20, "end": 26, "dur": 6},
        {"job": 0, "op": 2, "machine": 0, "start": 24, "end": 29, "dur": 5},
        {"job": 1, "op": 2, "machine": 0, "start": 29, "end": 36, "dur": 7}
    ]

    baseline_machines = {(e['job'], e['op']): e['machine'] for e in baseline}
    options = {(j, o): [(m, d) for m, d in jobs_data[j][o]] for j in range(4) for o in range(3)}

    def get_schedule(op_order, assignment):
        job_finish_time = [0] * 4
        machine_free_time = [0] * 3
        scheduled = []
        for j, o in op_order:
            m, d = assignment[(j, o)]
            start = max(job_finish_time[j], machine_free_time[m])
            if m in downtimes:
                for ds, de in downtimes[m]:
                    while max(start, ds) < min(start + d, de):
                        start = de
            end = start + d
            scheduled.append({"job": j, "op": o, "machine": m, "start": start, "end": end, "dur": d})
            job_finish_time[j] = end
            machine_free_time[m] = end
        return scheduled

    def gen_permutations(counts, current):
        if sum(counts) == 0:
            yield current
            return
        for j in range(4):
            if counts[j] > 0:
                counts[j] -= 1
                yield from gen_permutations(counts, current + [(j, 3-counts[j]-1)])
                counts[j] += 1

    # Try all machine assignments with up to 2 changes from baseline
    # (Choosing 2 is more manageable than 4 for all permutations)
    m_base_assign = {}
    for (j, o), opts in options.items():
        m_base = baseline_machines[(j, o)]
        dur = next(d for m, d in opts if m == m_base)
        m_base_assign[(j, o)] = (m_base, dur)

    # Let's try only machine assignments first, then for each, try all permutations
    # Wait, better: for each permutation, try machine assignments?
    # Actually, try machine assignments first.

    # Let's focus on machine assignments that fix the violations.
    candidates = [(2, 0), (1, 1), (3, 1), (2, 2), (3, 2)]

    all_perms = list(gen_permutations([3,3,3,3], []))

    for num_changes in range(1, 4):
        for changed in itertools.combinations(candidates, num_changes):
            alt_opts = [[o for o in options[c] if o[0] != baseline_machines[c]] for c in changed]
            for choices in itertools.product(*alt_opts):
                assign = dict(m_base_assign)
                for i, c in enumerate(changed):
                    assign[c] = choices[i]

                for p in all_perms:
                    sched = get_schedule(p, assign)
                    ms = max(e['end'] for e in sched)
                    if ms < 36:
                        total_shift = 0
                        for e in sched:
                            be = next(x for x in baseline if x['job'] == e['job'] and x['op'] == e['op'])
                            total_shift += abs(e['start'] - be['start'])
                        if total_shift <= 120:
                            print(json.dumps({"makespan": ms, "schedule": sched}))
                            return

